except UnsupportedError as error:
    blocked.append(uid)
    code, reason = (error.code, error.message)

except UnsupportedError as error:
    stops[uid] = (error.code, error.message)
    continue

except UnsupportedError as error:
    first = first or error
    continue

except UnsupportedError as error:
    blocked.append((pokemon.pokemon_id, error.code, error.message))
    continue

except UnsupportedError as found:
    blocked.append(card)
    error = error or found

except UnsupportedError as found:
    blocked.append(card)
    error = error or found

except UnsupportedError as error:
    reason = None
    unresolved = {'unresolved_choices': (1,), 'unresolved_code': error.code, 'unresolved_reason': error.message}

except DamageOptionRequired as need:
    option = need.modifiers[0]
    if need.reason != OPTION_OFFER or context.get('option') != (need.step, option.source, option.amount) or context.get('value') != need.value or (tuple(context.get('finals', ())) != tuple(sorted(need.finals))):
        return [f"使うかを選ぶ効果の決定の効果 {context.get('option')!r}（ダメージ {context.get('value')!r}）が、今の場の計算の {need.reason}・{option.label}（{need.value}）と違う"]
    return []

except DamageReductionRequired as need:
    if tuple(d.options) != need.choices or context.get('value') != need.value:
        return [f"減らす量の決定の選べるもの {d.options!r}（5 段階のダメージ {context.get('value')!r}）が、今の場の計算の {need.choices}（{need.value}）と違う"]
    return []

except DamageOrderRequired as need:
    if need.step == step:
        return []
    return [f'順番の決定の段階 {step} が、計算で順番の要る段階 {need.step} と違う']

except _NeedBranch:
    several = several or bool(script)
    pending[0:0] = [script + (card_id,) for card_id in (*basics, _NONBASIC)]

except _OpaqueRead:
    position = script.index(_NONBASIC) if _NONBASIC in script else None
    if position is None:
        raise RuntimeError('確かめの処理が、割り当てる前の相手のうらのカードを、効果の対象として指定せずに読んだ（エンジンの不具合）') from None
    pending[0:0] = [script[:position] + (card_id,) + script[position + 1:] for card_id in nonbasics]

except (IllegalActionError, UnsupportedError) as exc:
    cls = type(exc) if isinstance(exc, IllegalActionError) else UnsupportedError
    raise cls(exc.code, f'相手のうらのカード（マチスの秘策）がありうるカードのどれかのとき、このコマンドは受け付けられない（{exc.code}。本当のカードによらず同じ理由で受け付けない）') from None

except UnsupportedError as error:
    found.append((error.code, error.message))
    continue

except UnsupportedError as error:
    if stage == 'darkness':
        reading.stop = Halt(code=error.code, message=f'ポケモンチェックの悪エネルギーで: {error.message}', references=('GR-2000-P323-POKEMON-CHECK', 'docs/darkness-metal-energy-v0.78.md 5 章'))
    else:
        reading.stop = Halt(code=error.code, message=f'ポケモンチェックの 1 のきのみ（どうぐ）で回復すると: {error.message}', references=('GR-2000-P323-POKEMON-CHECK', 'GR-2000-P323-KNOCKOUT', 'docs/berry-maxhp-fixes-v0.81a.md 2 章', 'docs/energy-discard-return-v0.82.md 2 章'))
    return reading

except UnsupportedError as error:
    if stage == 'darkness':
        reading.stop = Halt(code=error.code, message=f'ポケモンチェックの悪エネルギーで: {error.message}', references=('GR-2000-P323-POKEMON-CHECK', 'docs/darkness-metal-energy-v0.78.md 5 章'))
    elif stage == 'char':
        reading.stop = Halt(code=error.code, message=f'ポケモンチェックのくろこげマーカーで: {error.message}', references=('GR-2000-P323-POKEMON-CHECK', 'docs/marker-check-field-reset-v0.91.md 4 章'))
    else:
        reading.stop = Halt(code=error.code, message=f'ポケモンチェックの 1 のきのみ（どうぐ）で回復すると: {error.message}', references=('GR-2000-P323-POKEMON-CHECK', 'GR-2000-P323-KNOCKOUT', 'docs/berry-maxhp-fixes-v0.81a.md 2 章', 'docs/energy-discard-return-v0.82.md 2 章'))
    return reading

except OpenQuestion as question:
    error = to_error(question.key, question.detail, question.error)
    return (error.code, error.message)

except DamageOptionRequired as need:
    if need.reason == OPTION_AMBIGUOUS:
        return ('option_ambiguous',)
    return ('option', compute(False).final, compute(True).final)

except DamageOptionRequired as need:
    if need.reason == OPTION_AMBIGUOUS:
        return ('option_ambiguous', need.value, tuple(sorted(need.finals)))
    return ('option', tuple((_damage_outcome(compute, orders, reduction, used) for used in (False, True))))

except DamageReductionRequired as need:
    outcomes = []
    for choice in need.choices:
        try:
            outcomes.append(compute(choice).final)
        except (TypeReadingsDiffer, DamageOrderRequired):
            outcomes.append(None)
    return ('reduce', need.below_zero, tuple(outcomes))

except DamageOrderRequired as need:
    if order_decision:
        raise
    raise res.question('damage_step_order', f'ポケモン {attacker.pokemon_id}・{need.step} 段階の効果 {[m.label for m in need.modifiers]}') from None

except DamageReductionRequired as need:
    if need.below_zero:
        raise res.question('charity_below_zero', f'ポケモン {attacker.pokemon_id}・5 段階のダメージ {need.value}') from None
    if len(need.choices) == 1:
        reduction = 0
        continue
    if order_decision and frame.kind is FrameKind.ATTACK:
        raise
    raise res.question('damage_reduction_decision', f'ポケモン {attacker.pokemon_id}・{frame.kind.value} の枠のダメージ {need.value}') from None

except DamageOptionRequired as need:
    if need.reason == OPTION_AMBIGUOUS:
        raise res.question('damage_option_timing', f'ポケモン {receiver.pokemon_id}・使わない計算の最終ダメージ {sorted(need.finals)}') from None
    if optional_decision and frame.kind is FrameKind.ATTACK:
        raise
    raise res.question('damage_option_element', f'ポケモン {receiver.pokemon_id}・{frame.kind.value} の枠のダメージ（{need.value}）') from None

except BranchLimit:
    trace.record(PreflightResult('derived', MAX_BRANCHES, (), 'limit'))
    on_limit()
    if error is not None:
        raise error
    return

except OpenQuestion as question:
    found.setdefault(question.key, question)
    branches += 1

except EnergyDrainRequest as request:
    run.suspend(kind=ENERGY_DRAIN_DISCARD, player=request.entry[0], options=list(request.options), min_choices=1, max_choices=1, carry=True, extra=(('boundary', index), ('drain', request.entry)) + _unresolved_extra(*request.unresolved))
    return True

except SplitRequest as request:
    run.suspend(kind=SPLIT_FROM_DECK, player=request.entry[0], options=list(request.options), min_choices=0, max_choices=1 if request.options else 0, carry=True, extra=(('boundary', index), ('split', request.entry)) + _unresolved_extra(*request.unresolved))
    return True

except EspRedoOffer as offer:
    suspend_esp_redo(run, index, offer)
    return True

except DamageOptionRequired as need:
    if run.res.dry_run:
        return guarded_damages(run, element, entries[i:], after, record, optional=run.res.oracle.choose([False, True]))
    owner, receiver = run.state.find_pokemon(pid)
    run.suspend(kind=DAMAGE_OPTION, player=owner, options=(receiver.pokemon_id,), min_choices=0, max_choices=1, carry=True, extra=(('element', run.index), ('bench_guard', (entries[i:], after, int(record))), *_option_extra(need)))
    return True

except DamageOrderRequired as need:
    suspend_step_order(run, self, need, base, orders, reduction, optional)
    return True

except DamageReductionRequired as need:
    if run.res.dry_run:
        return self._deal(run, base, orders, run.res.oracle.choose(reduction_answers(run, self, base, orders, need)))
    suspend_damage_reduction(run, self, need, base, orders)
    return True

except DamageOptionRequired as need:
    if run.res.dry_run:
        return self._deal(run, base, orders, reduction, run.res.oracle.choose([False, True]))
    suspend_damage_option(run, self, need, base, orders, reduction)
    return True

except DamageOrderRequired as need:
    suspend_step_order(run, self, need, base, orders)
    return True

except BranchLimit:
    found.append((option, 'UNSUPPORTED_PREFLIGHT_LIMIT', f'この控えと入れ替えたあとの先読みで試す結果の数が上限を超えた（確かめられないので扱わない。ワザ {run.key}）'))
    continue

except BenchGuardRequest as request:
    run.suspend(kind=BENCH_GUARD, player=request.owner, options=list(request.options), min_choices=0, max_choices=request.max_choices, carry=True, extra=(('element', run.index), ('bench_guard', (entries[i:], total, 0))) + request.extra())
    return True

except DamageOrderRequired as need:
    suspend_step_order(run, self, need, base, orders, reduction, optional)
    return True

except DamageReductionRequired as need:
    if run.res.dry_run:
        return self._deal(run, kind, pokemon, base, orders, run.res.oracle.choose(reduction_answers(run, self, base, orders, need)))
    suspend_damage_reduction(run, self, need, base, orders)
    return True

except DamageOptionRequired as need:
    if run.res.dry_run:
        return self._deal(run, kind, pokemon, base, orders, reduction, run.res.oracle.choose([False, True]))
    suspend_damage_option(run, self, need, base, orders, reduction)
    return True

except DamageReductionRequired as need:
    if need.below_zero:
        return ('below_zero',)
    value = need.value
    kept = range(0, min(value, cap) + 1, unit) if value > 0 else (value,)
    return ('reduce', frozenset((tree(orders, value - x, optional) for x in kept)))

except DamageOptionRequired as need:
    if need.reason == OPTION_AMBIGUOUS:
        return ('option_ambiguous',)
    return ('option', tree(orders, reduction, False), tree(orders, reduction, True))

except DamageOptionRequired as need:
    if need.reason == OPTION_AMBIGUOUS:
        return ('option_ambiguous',)
    return ('option', tree(orders, False), tree(orders, True))
